@@ -0,0 +1,143 @@
+/**
+ * @file main.c
+ * @brief Chương trình chính khởi tạo phần cứng, thiết lập 2 tác vụ mẫu
+ *        giao tiếp qua hàng đợi tĩnh IPC và khởi chạy nhân RTOS tiền định.
+ */
+
+#include "rtos/rtos_types.h"
+#include "stm32f469xx.h"
+#include "stm32f4xx_hal.h"
+
+/* Cấu trúc gói tin truyền qua hàng đợi IPC */
+typedef struct {
+    uint32_t sender_id;
+    uint32_t sequence;
+    uint32_t timestamp;
+} app_msg_t;
+
+#define APP_QUEUE_CAPACITY 8U
+
+/* Vùng nhớ tĩnh cho hàng đợi và các tác vụ */
+static app_msg_t queue_storage[APP_QUEUE_CAPACITY];
+static rtos_queue_t app_queue;
+
+static rtos_tcb_t producer_tcb;
+static uint32_t producer_stack[RTOS_DEFAULT_STACK_WORDS];
+
+static rtos_tcb_t consumer_tcb;
+static uint32_t consumer_stack[RTOS_DEFAULT_STACK_WORDS];
+
+/* Biến thống kê trạng thái ứng dụng */
+static volatile uint32_t g_messages_sent = 0;
+static volatile uint32_t g_messages_received = 0;
+
+/**
+ * @brief Đồng bộ bộ đếm thời gian của HAL với nhịp của RTOS.
+ */
+uint32_t HAL_GetTick(void)
+{
+    return rtos_get_tick_count();
+}
+
+/**
+ * @brief Hàm trễ phần cứng thích ứng với RTOS delay.
+ */
+void HAL_Delay(uint32_t Delay)
+{
+    rtos_delay_ms(Delay);
+}
+
+/**
+ * @brief Tác vụ sản xuất (Producer Task) - Mức ưu tiên 1.
+ *        Định kỳ đóng gói dữ liệu và gửi vào hàng đợi tĩnh IPC.
+ */
+static void producer_task(void *arg)
+{
+    (void)arg;
+    uint32_t seq = 0;
+
+    while (1) {
+        app_msg_t msg;
+        msg.sender_id = 1U;
+        msg.sequence = ++seq;
+        msg.timestamp = rtos_get_tick_count();
+
+        /* Gửi thông điệp vào hàng đợi với thời gian chờ 50 ms */
+        if (rtos_queue_send(&app_queue, &msg, 50U) == RTOS_OK) {
+            g_messages_sent++;
+        }
+
+        /* Tác vụ ngủ 100 ms nhường CPU cho tác vụ khác */
+        rtos_delay_ms(100U);
+    }
+}
+
+/**
+ * @brief Tác vụ tiêu thụ (Consumer Task) - Mức ưu tiên 2.
+ *        Lấy thông điệp từ hàng đợi và xử lý dữ liệu.
+ */
+static void consumer_task(void *arg)
+{
+    (void)arg;
+
+    while (1) {
+        app_msg_t rx_msg;
+
+        /* Chờ nhận dữ liệu từ hàng đợi với thời gian chờ 200 ms */
+        if (rtos_queue_receive(&app_queue, &rx_msg, 200U) == RTOS_OK) {
+            g_messages_received++;
+        }
+
+        /* Nhường quyền hoặc xử lý tiếp */
+        rtos_yield();
+    }
+}
+
+/**
+ * @brief Điểm khởi nhập chính của ứng dụng firmware.
+ */
+int main(void)
+{
+    /* 1. Khởi tạo lõi RTOS và cấu trúc điều phối */
+    rtos_init();
+
+    /* 2. Khởi tạo hàng đợi tĩnh IPC */
+    rtos_queue_init(
+        &app_queue,
+        queue_storage,
+        sizeof(app_msg_t),
+        APP_QUEUE_CAPACITY
+    );
+
+    /* 3. Tạo tác vụ Producer (Mức ưu tiên 1) */
+    rtos_task_create(
+        &producer_tcb,
+        "Producer",
+        producer_task,
+        NULL,
+        1U,
+        producer_stack,
+        RTOS_DEFAULT_STACK_WORDS
+    );
+
+    /* 4. Tạo tác vụ Consumer (Mức ưu tiên 2) */
+    rtos_task_create(
+        &consumer_tcb,
+        "Consumer",
+        consumer_task,
+        NULL,
+        2U,
+        consumer_stack,
+        RTOS_DEFAULT_STACK_WORDS
+    );
+
+    /* 5. Khởi động bộ lập lịch RTOS tiền định */
+    rtos_start();
+
+    /* Bẫy vòng lặp nếu nhân bị dừng bất thường */
+    while (1) {
+        __WFI();
+    }
+
+    return 0;
+}

