/**
 * @brief Tác vụ giao diện người dùng và cảm ứng - Mức ưu tiên 3.
 *        Khởi tạo LCD DSI, SDRAM FMC, FT6206 và quét tương tác chạm.
 */
static void ui_task(void *arg)
{
    (void)arg;
    uint16_t x = 0;
    uint16_t y = 0;

    UI_Init();
    Touch_Init();

    while (1) {
        if (Touch_Read(&x, &y)) {
