{
    /* 1. Khởi tạo lõi RTOS và cấu trúc điều phối */
    rtos_init();

    /* 2. Khởi tạo hàng đợi tĩnh IPC */
    rtos_queue_init(
        &app_queue,
        queue_storage,
        sizeof(app_msg_t),
        APP_QUEUE_CAPACITY
    );

    /* 3. Tạo tác vụ Producer (Mức ưu tiên 1) */
    rtos_task_create(
        &producer_tcb,
        "Producer",
        producer_task,
        NULL,
        1U,
        producer_stack,
        RTOS_DEFAULT_STACK_WORDS
    );

